int32_t len = (int32_t)std::min<size_t>((size_t)chosen, s.size());
// Prepare an 8-byte aligned local buffer to avoid alignment faults on strict platforms.
alignas(8) unsigned char aligned_buf[1024];
const void *key_ptr = nullptr;
if (len > 0) {
  // Copy exactly len bytes into aligned storage.
  if (len > 1024) { FUZZ_BAIL(); }
  memcpy(aligned_buf, s.data(), (size_t)len);
  key_ptr = aligned_buf;
} else {
  // len == 0: key can be null per typical Murmur semantics, but we avoid UB by passing a non-null pointer that's unused.
  key_ptr = aligned_buf; // unused since len==0
}
// Call the target function.
volatile uint64_t h = oceanbase::common::murmurhash64A(key_ptr, len, seed);
(void)h;
